std::string str(const zchar_t* s) { return s ? std::string(s) : std::string(); }

std::string jsonStr(const nlohmann::json& j, const char* key) {
  auto it = j.find(key);
  return (it != j.end() && it->is_string()) ? it->get<std::string>() : std::string();
}

